function normalizeMA(config){if(!Array.isArray(config)||config.length!==4)throw Error('均線設定格式無效');return config.map((c,i)=>{if(typeof c.visible!=='boolean'||!Number.isInteger(c.period)||c.period<1||c.period>300)throw Error('均線週期請填入1～300的整數');return {period:c.period,visible:c.visible}})}
function readMA(){return normalizeMA(maDefaults.map((fallback,i)=>{const period=Number($('ma'+(i+1)).value),visible=$('maVisible'+(i+1)).checked;return {period:!visible&&(!Number.isInteger(period)||period<1||period>300)?fallback:period,visible}}))}
function applyMASettings(config){maPeriods=config.filter(c=>c.visible).map(c=>c.period);updateMALegend();if(r)drawChart($('chart'),r)}
function writeMAFields(config){config.forEach((c,i)=>{$('ma'+(i+1)).value=c.period;$('maVisible'+(i+1)).checked=c.visible})}
$('applyMA').onclick=()=>{try{applyMASettings(readMA())}catch(e){toast(e.message)}};
$('saveMA').onclick=()=>{try{const c=readMA();localStorage.setItem(maStorageKey,JSON.stringify(c));applyMASettings(c);$('maSaveState').textContent='已儲存並套用，下次開啟沿用。設定僅保存在目前瀏覽器。';toast('均線已儲存並套用')}catch(e){$('maSaveState').textContent='未完成儲存：'+e.message;toast('未完成儲存：'+e.message)}};
$('resetMA').onclick=()=>{const c=maDefaults.map(period=>({period,visible:true}));writeMAFields(c);applyMASettings(c);try{localStorage.setItem(maStorageKey,JSON.stringify(c));$('maSaveState').textContent='已重設並儲存：5、10、15、30分鐘，顯示四條均線。';toast('均線已重設')}catch(e){$('maSaveState').textContent='本次已重設，但無法儲存至瀏覽器；重新開啟可能載入舊設定。';toast('本次已重設，儲存失敗：'+e.message)}};
try{const saved=localStorage.getItem(maStorageKey);if(saved){const c=normalizeMA(JSON.parse(saved));writeMAFields(c);applyMASettings(c);$('maSaveState').textContent='已載入儲存的均線設定。設定僅保存在目前瀏覽器。'}}catch{$('maSaveState').textContent='無法讀取儲存設定，使用預設值。'}

function zoomChart(factor){if(!r)return;const current=chartWindow??Math.max(12,r.bars.length);chartWindow=Math.max(8,Math.min(1000,Math.round(current*factor)));chartOffset=Math.min(chartOffset,Math.max(0,r.bars.length-chartWindow));drawChart($('chart'),r)}
$('zoomIn').onclick=()=>zoomChart(.7);$('zoomOut').onclick=()=>zoomChart(1.45);$('fitChart').onclick=()=>{chartWindow=null;chartOffset=0;if(r)drawChart($('chart'),r)};
function panChart(direction){if(!r)return;if(chartWindow===null)chartWindow=Math.max(8,Math.ceil(r.bars.length/2));chartOffset=Math.max(0,Math.min(Math.max(0,r.bars.length-chartWindow),chartOffset+direction*Math.max(1,Math.round(chartWindow/3))));drawChart($('chart'),r)}
$('panEarlier').onclick=()=>panChart(1);$('panLater').onclick=()=>panChart(-1);$('followChart').onclick=()=>{chartOffset=0;if(r)drawChart($('chart'),r)};
$('chartScroll').oninput=()=>{chartOffset=Number($('chartScroll').max)-Number($('chartScroll').value);if(r)drawChart($('chart'),r)};
let chartDrag=null,chartDragged=false;
$('chart').addEventListener('pointerdown',e=>{if(e.button!==0||!chartGeometry)return;chartDrag={x:e.clientX,offset:chartOffset};chartDragged=false;$('chart').setPointerCapture(e.pointerId)});
$('chart').addEventListener('pointermove',e=>{if(chartDrag&&r&&chartWindow!==null){const delta=e.clientX-chartDrag.x;if(Math.abs(delta)>4)chartDragged=true;chartOffset=Math.max(0,Math.min(Math.max(0,r.bars.length-chartWindow),chartDrag.offset+Math.round(delta/chartGeometry.step)));drawChart($('chart'),r)}else{const box=$('chart').getBoundingClientRect(),x=e.clientX-box.left,y=e.clientY-box.top;const hit=chartHitTargets.find(t=>Math.hypot(t.x-x,t.y-y)<10);$('chart').title=hit?`${hit.order.side===1?'買進':'賣出'} ${hit.order.action??(hit.order.close?'出場':'進場')} ${hit.order.fillPrice}，${hit.order.filledQty??hit.order.qty}口，${time(hit.order.fillTime)}，來源列序${hit.order.fillRow}`:'拖曳查看較早或較晚走勢；Ctrl＋滾輪縮放'}});
$('chart').addEventListener('pointerup',()=>chartDrag=null);$('chart').addEventListener('pointercancel',()=>chartDrag=null);
$('chart').addEventListener('wheel',e=>{if(!e.ctrlKey)return;e.preventDefault();zoomChart(e.deltaY>0?1.2:.8)},{passive:false});
$('chart').addEventListener('click',async e=>{if(chartDragged)return;const box=$('chart').getBoundingClientRect(),x=e.clientX-box.left,y=e.clientY-box.top,hit=chartHitTargets.find(t=>Math.hypot(t.x-x,t.y-y)<10);if(!hit)return;const o=hit.order;await modal(`<h2>${o.side===1?'買進':'賣出'} · ${esc(o.action??(o.close?'出場':'進場'))}</h2><p>成交價 ${num(o.fillPrice)} ／ ${num(o.filledQty??o.qty)}口 ／ ${time(o.fillTime)}</p><p>來源列序：${num(o.fillRow)} ／ 委託 #${o.id}</p><p>平倉 ${num(o.closeQty??(o.close?o.qty:0))}口；開倉 ${num(o.openQty??(o.close?0:o.qty))}口</p>`,{ok:'關閉',cancel:false})});
updateMALegend();
function drawChart(canvas,state,upto=null,exportSize=null){
 const ticks=state.data.ticks;let bars=state.bars;
 if(upto!==null){bars=[];for(let i=0;i<=Math.min(upto,ticks.length-1);i++){const t=ticks[i],m=Math.floor(t[0]/60);let b=bars.at(-1);if(!b||b.minute!==m){b={minute:m,open:t[1],high:t[1],low:t[1],close:t[1],volume:0};bars.push(b)}b.high=Math.max(b.high,t[1]);b.low=Math.min(b.low,t[1]);b.close=t[1];b.volume+=t[2]}}
 const main=canvas.id==='chart',box=exportSize??canvas.getBoundingClientRect(),w=box.width,h=box.height;if(w<10||h<10||!bars.length)return;
 const dpr=exportSize?2:(devicePixelRatio||1);canvas.width=w*dpr;canvas.height=h*dpr;const c=canvas.getContext('2d');c.scale(dpr,dpr);c.fillStyle='#172127';c.fillRect(0,0,w,h);
 const {start,end}=getChartWindow(bars.length,main?chartWindow:null,main?chartOffset:0),visible=bars.slice(start,end),left=18,right=74,top=24,bottom=Math.round(h*.70),chartW=w-left-right,layout=candleLayout(chartW,visible.length,main?chartWindow:null),step=layout.step,x=i=>left+(i+.5)*step;
 const averages=maPeriods.map(p=>movingAverage(bars,p));let min=Math.min(...visible.map(b=>b.low)),max=Math.max(...visible.map(b=>b.high));
 const filled=state.orders.filter(o=>o.status==='filled'&&(upto===null||o.fillIndex<=upto)&&ticks[o.fillIndex]);
 for(const o of filled){const m=Math.floor(ticks[o.fillIndex][0]/60);if(m>=visible[0].minute&&m<=visible.at(-1).minute){min=Math.min(min,o.fillPrice);max=Math.max(max,o.fillPrice)}}
 for(const values of averages)for(let i=start;i<end;i++)if(values[i]!=null){min=Math.min(min,values[i]);max=Math.max(max,values[i])}
 const open=ticks[0][1];if(start===0){min=Math.min(min,open);max=Math.max(max,open)}const pad=Math.max(6,(max-min)*.15);min-=pad;max+=pad;const y=v=>top+(max-v)/(max-min)*(bottom-top);
 c.font='11px Arial';c.lineWidth=1;for(let j=0;j<=5;j++){const yy=top+(bottom-top)*j/5;c.strokeStyle='#29373f';c.beginPath();c.moveTo(left,yy);c.lineTo(w-right+5,yy);c.stroke();c.fillStyle='#91a3ad';c.fillText(num(max-(max-min)*j/5),w-right+12,yy+3)}
 const gridN=Math.min(Math.max(1,Math.floor(step*visible.length/95)),visible.length);for(let j=0;j<gridN;j++){const i=Math.floor(j*(visible.length-1)/Math.max(1,gridN-1)),xx=x(i);c.strokeStyle='#233139';c.beginPath();c.moveTo(xx,top);c.lineTo(xx,h-30);c.stroke();c.fillStyle='#91a3ad';c.fillText(time(visible[i].minute*60).slice(0,5),Math.max(left,xx-16),h-12)}
 // Only the opening reference remains a horizontal annotation. Trades use priced dots.
 if(open>=min&&open<=max){c.strokeStyle='#b9a16c';c.setLineDash([4,4]);c.beginPath();c.moveTo(left,y(open));c.lineTo(w-right+5,y(open));c.stroke();c.setLineDash([]);c.fillStyle='#b9a16c';c.fillText('開盤 '+num(open),left+4,y(open)-6)}
 const width=Math.max(1,Math.min(14,step*.82)),vmax=Math.max(...visible.map(b=>b.volume));visible.forEach((b,i)=>{const col=b.close>=b.open?'#fa7e79':'#5bc9ae',xx=x(i);c.strokeStyle=col;c.fillStyle=col;c.beginPath();c.moveTo(xx,y(b.high));c.lineTo(xx,y(b.low));c.stroke();c.fillRect(xx-width/2,Math.min(y(b.open),y(b.close)),width,Math.max(1,Math.abs(y(b.close)-y(b.open))));c.globalAlpha=.62;c.fillRect(xx-width/2,h-30-b.volume/vmax*Math.max(25,h*.22),width,b.volume/vmax*Math.max(25,h*.22));c.globalAlpha=1});
 averages.forEach((values,k)=>{c.save();c.beginPath();c.rect(left,top,chartW,bottom-top);c.clip();c.strokeStyle=maColors[k];c.lineWidth=1.3;c.beginPath();let begun=false;for(let i=start;i<end;i++){if(values[i]==null)continue;const xx=x(i-start),yy=y(values[i]);if(!begun){c.moveTo(xx,yy);begun=true}else c.lineTo(xx,yy)}c.stroke();c.restore()});
 const hitTargets=[],occupied=[];
 for(const o of filled){const m=Math.floor(ticks[o.fillIndex][0]/60),i=visible.findIndex(b=>b.minute===m);if(i<0)continue;const xx=x(i),yy=y(o.fillPrice),color=o.side===1?'#ff6964':'#48d3aa';c.fillStyle=color;c.strokeStyle='#111b21';c.lineWidth=1.5;c.beginPath();c.arc(xx,yy,4.5,0,Math.PI*2);c.fill();c.stroke();hitTargets.push({x:xx,y:yy,order:o});
  const text=`${o.side===1?'買':'賣'}${o.action??(o.close?'出場':'進場')} ${num(o.fillPrice)} ×${o.filledQty??o.qty}`,tw=c.measureText(text).width+8;let tx=Math.max(left,Math.min(w-right-tw,xx+7)),ty=yy-12;
  for(let attempt=0;attempt<16;attempt++){const direction=attempt%2===0?-1:1;ty=Math.max(top+11,Math.min(bottom-3,yy+direction*(12+Math.floor(attempt/2)*15)));const overlaps=occupied.some(b=>tx<b.x+b.w&&tx+tw>b.x&&ty-12<b.y+3&&ty>b.y-12);if(!overlaps)break}
  occupied.push({x:tx,y:ty,w:tw});c.fillStyle='#142027e8';c.fillRect(tx-3,ty-11,tw,15);c.fillStyle=color;c.fillText(text,tx,ty);
 }
 const last=visible.at(-1);c.fillStyle=last.close>=last.open?'#d06e69':'#378e7a';c.fillRect(w-right+6,y(last.close)-10,right-8,20);c.fillStyle='#fff';c.fillText(num(last.close),w-right+11,y(last.close)+3);c.fillStyle='#8199a6';c.fillText('成交量（單邊）',left+3,bottom+22);
 if(main){chartHitTargets=hitTargets;chartGeometry={step};const maxOffset=Math.max(0,bars.length-(chartWindow??bars.length));chartOffset=Math.min(chartOffset,maxOffset);$('chartScroll').max=maxOffset;$('chartScroll').value=maxOffset-chartOffset;$('chartScroll').disabled=maxOffset===0;$('chartRange').textContent=chartWindow===null?'完整走勢':`顯示${visible.length}根`;$('chartViewInfo').textContent=`${time(visible[0].minute*60).slice(0,5)}～${time(last.minute*60).slice(0,5)}`;$('panEarlier').disabled=start===0;$('panLater').disabled=end===bars.length;$('followChart').disabled=chartOffset===0;}
}

async function inspectTrade(t,state){const promise=modal(`<h2>交易檢討 · ${t.side===1?'多單':'空單'} ${esc(t.qty)} 口</h2><p>${time(t.entryTime)} @ ${num(t.entry,2)} → ${time(t.exitTime)} @ ${num(t.exit)} ｜ ${esc(t.reason)}</p><div style="height:290px"><canvas id="reviewChart"></canvas></div><p>進場來源列序 ${num(t.entryRow)} ／ 觸發來源列序 ${num(t.triggerRow)} ／ 出場來源列序 ${num(t.exitRow)}</p><p>設定價 ${num(t.level)} ／觸發成交價 ${num(t.triggerPrice)} ／ 模擬出場價 ${num(t.exit)}</p><p>MFE ${num(t.mfe)} 點 ／ MAE ${num(t.mae)} 點 ／ 成本 ${num(t.cost)} ／ 淨損益 ${signed(t.net)}</p><p>圖表只回放至此筆出場位置。</p>`,{ok:'關閉',cancel:false});requestAnimationFrame(()=>drawChart($('reviewChart'),state,t.exitIndex));await promise}
new ResizeObserver(()=>{if(r)drawChart($('chart'),r)}).observe($('chart'));
const openDB=()=>new Promise((resolve,reject)=>{let expired=false;const timer=setTimeout(()=>{expired=true;reject(Error('瀏覽器儲存空間未回應，請先匯出紀錄'))},5000);const q=indexedDB.open('rule-f-practice',1);q.onupgradeneeded=()=>q.result.createObjectStore('sessions',{keyPath:'id'});q.onsuccess=()=>{clearTimeout(timer);if(expired)q.result.close();else resolve(q.result)};q.onerror=()=>{clearTimeout(timer);reject(q.error)};q.onblocked=()=>{clearTimeout(timer);expired=true;reject(Error('儲存空間被其他分頁占用，請關閉舊分頁再重試'))}});
function dbOp(mode,action){return new Promise((resolve,reject)=>{const tx=(()=>{if(!db)throw Error('目前瀏覽器無法保存績效，請匯出本次 JSON');return db.transaction('sessions',mode)})(),store=tx.objectStore('sessions');let result;const q=action(store);if(q)q.onsuccess=()=>result=q.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error)})}
function download(data,name){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),3000)}
const savedSessions=new SessionArchive();let savingSession=false;
async function saveSession({askName=false}={}){
 if(!r||loading||savingSession)return;pause();const target=r,prior=savedSessions.get(target);let name=prior?.name??`${target.data.date} TX${target.data.contract} ${target.cfg.auto?'自動':'手動'}練習`;
 if(askName){name=await modal(`<h2>保存本次練習</h2><p>保存後會歸入歷史累積績效。同一次練習再次保存會更新該筆紀錄。</p><input id="dialogInput" maxlength="100" value="${esc(name)}">`,{ok:'儲存'});if(name===null)return}
 savingSession=true;$('savePerformance').disabled=true;let snap=target.snapshot(String(name).trim().slice(0,100)||'未命名練習',$('note').value);const savedEventCount=target.events.length;
 try{snap=await savedSessions.put(target,snap,record=>dbOp('readwrite',store=>store.put(record)));if(r===target){saveIndex=snap.index;if(target.i===snap.index&&target.events.length===savedEventCount&&$('note').value===snap.note)dirty=false}$('performanceSaved').textContent='已儲存：'+snap.name+'；同次練習再次儲存會更新，不重複累加。';await loadHistory();toast('已儲存並歸入歷史累積績效')}
 catch(e){$('performanceSaved').textContent='儲存失敗：'+e.message+'。請先匯出本次紀錄。';toast('儲存失敗，請先匯出本次紀錄：'+e.message)}finally{savingSession=false;$('savePerformance').disabled=false}
}
$('save').onclick=()=>saveSession({askName:true});
$('savePerformance').onclick=()=>saveSession();
$('saveChart').onclick=async()=>{
 if(!r||!r.bars.length||loading){toast('請先載入並播放行情');return}
 pause();const button=$('saveChart');button.disabled=true;
 try{
  const state=r,upto=state.i,width=Math.max(1600,Math.min(3200,state.bars.length*10+100)),height=850;
  const plot=document.createElement('canvas');drawChart(plot,state,upto,{width,height});
  const image=document.createElement('canvas');image.width=plot.width;image.height=plot.height+160;const c=image.getContext('2d');
  c.fillStyle='#172127';c.fillRect(0,0,image.width,image.height);c.drawImage(plot,0,120);
  c.fillStyle='#d9bd79';c.font='bold 30px Arial';c.fillText(`曾阿牛的期貨島 · TX ${state.data.contract} · ${state.data.date}`,36,42);
  c.fillStyle='#a5b4bd';c.font='24px Arial';c.fillText(`已播放 ${time(state.data.ticks[0][0])}～${time(state.data.ticks[upto][0])} ｜1分鐘K ｜紅點買進／綠點賣出 ｜均線 ${maPeriods.length?maPeriods.join('、'):'關閉'}`,36,88);
  const result=await saveChartImage(image,`${state.data.date}走勢.png`);
  if(result==='saved')toast('走勢圖已儲存');else if(result==='download')toast('已下載走勢圖；儲存位置依瀏覽器設定。可開啟「下載前詢問儲存位置」。');
 }catch(e){toast('走勢圖未儲存：'+e.message)}finally{button.disabled=false}
};
$('dailyPerformance').onclick=()=>{if(!r){toast('請先載入行情');return}pause();$('dailyPerformanceContent').innerHTML=statsHTML(r.stats());$('performanceSaved').textContent=savedSessions.has(r)?'此練習已有保存紀錄；再次儲存會更新。':'尚未儲存。儲存後會歸入歷史累積績效。';$('performanceDialog').showModal()};
$('export').onclick=()=>{if(r){pause();download(r.snapshot('匯出練習',$('note').value),`RULEF_${r.data.date}_${Date.now()}.json`)}};
async function loadHistory(){try{allRecords=await dbOp('readonly',s=>s.getAll());aggregateDirty=true;renderHistory()}catch(e){toast('無法讀取績效簿：'+e.message)}}
function filtered(){const q=$('historyFilter').value.toLowerCase();return allRecords.filter(x=>!!x.deleted===trash&&`${x.name} ${x.date} ${x.contract}`.toLowerCase().includes(q)).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))}
function renderHistory(){const rows=filtered();if(aggregateDirty){$('historyAggregate').innerHTML=historySummaryHTML(aggregateHistory(allRecords));aggregateDirty=false;renderEntryTimeAnalysis()}$('historyAggregate').hidden=trash;$('entryTimeAnalysis').hidden=trash;if(openRecordId&&!rows.some(x=>x.id===openRecordId))closeReview();const sum=rows.reduce((a,x)=>{a.net+=x.net||0;a.trades+=x.trades.length;a.finished+=x.finished?1:0;return a},{net:0,trades:0,finished:0});$('historySummary').textContent=`顯示 ${rows.length} 筆保存練習（完成 ${sum.finished}、快照 ${rows.length-sum.finished}）｜交易 ${sum.trades} 筆｜累計成本後損益 TWD ${signed(sum.net)}。同次練習儲存會更新；舊版或匯入的獨立副本各自計入。`;$('trashBtn').textContent=trash?'返回績效簿':'查看回收筒';$('deleteAll').hidden=trash;$('historyList').innerHTML=rows.length?rows.map(x=>`<article class="panel historyCard"><div><h2>${esc(x.name)}</h2><small>${esc(x.date)} · TX ${esc(x.contract)} · ${x.finished?'已完成':'進度快照'} · ${num(x.trades.length)} 筆交易 · ${new Date(x.createdAt).toLocaleString('zh-TW')}</small></div><div class="actions"><strong class="${tone(x.net)}">${signed(x.net)}</strong><button data-open="${esc(x.id)}" aria-expanded="${openRecordId===x.id}">${openRecordId===x.id?'收回檢討':'檢討'}</button><button data-json="${esc(x.id)}">匯出</button><button data-delete="${esc(x.id)}">${trash?'還原':'移至回收筒'}</button></div></article>`).join(''):'<div class="panel empty">'+(trash?'回收筒沒有紀錄。':'尚無保存紀錄，完成練習後按「保存本次練習」。')+'</div>';$('historyList').querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openRecord(b.dataset.open));$('historyList').querySelectorAll('[data-json]').forEach(b=>b.onclick=()=>{const x=allRecords.find(x=>x.id===b.dataset.json);download(x,`RULEF_${x.date}_${x.id}.json`)});$('historyList').querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>toggleDelete(b.dataset.delete));}
$('historyFilter').oninput=renderHistory;$('trashBtn').onclick=()=>{trash=!trash;renderHistory()};
async function toggleDelete(id){const x=allRecords.find(x=>x.id===id);if(!trash){const yes=await modal(`<h2>移至回收筒？</h2><p>範圍：1 筆練習「${esc(x.name)}」，含 ${x.trades.length} 筆交易。僅影響目前瀏覽器，可從回收筒還原。</p><p>可先取消，再按該紀錄的「匯出」保存備份。</p>`,{ok:'移至回收筒'});if(!yes)return}x.deleted=!x.deleted;try{await dbOp('readwrite',s=>s.put(x));closeReview();aggregateDirty=true;renderHistory();toast(x.deleted?'已移至回收筒，可還原':'已還原練習')}catch(e){toast(e.message)}}
$('deleteAll').onclick=async()=>{const rows=filtered();if(!rows.length)return;const yes=await modal(`<h2>清除顯示範圍內的練習？</h2><p>共 ${rows.length} 筆練習、${rows.reduce((a,x)=>a+x.trades.length,0)} 筆交易，全部移至回收筒，可還原。原始行情保留。</p><p>如需備份，請先取消並按「匯出全部」。</p>`,{ok:'移至回收筒'});if(!yes)return;try{await dbOp('readwrite',s=>{for(const x of rows){x.deleted=true;s.put(x)}});closeReview();aggregateDirty=true;renderHistory();toast('已移至回收筒')}catch(e){toast(e.message)}};
$('exportAll').onclick=async()=>{await loadHistory();download({version:1,sessions:allRecords},`RULEF_全部練習_${Date.now()}.json`)};$('importBtn').onclick=()=>$('importFile').click();$('importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>50*1024*1024)throw Error('檔案超過 50MB');const content=JSON.parse(await file.text()),list=Array.isArray(content.sessions)?content.sessions:[content];if(list.length>500)throw Error('每次最多匯入 500 筆');for(const x of list)if(x.version!==1||typeof x.name!=='string'||!/^\d{8}$/.test(x.date)||!/^\d{6}$/.test(x.contract)||!Array.isArray(x.trades)||!Array.isArray(x.events)||!Array.isArray(x.orders)||!Array.isArray(x.equity)||!x.cfg||!x.stats||!Number.isFinite(x.index)||!Number.isFinite(x.net)||!Number.isFinite(Date.parse(x.createdAt)))throw Error('不是有效的 RULE F 練習檔');const yes=await modal(`<h2>匯入 ${list.length} 筆練習？</h2><p>會建立獨立副本，不覆寫現有紀錄。匯入結果視為外部紀錄，非重新驗證績效。</p>`,{ok:'匯入副本'});if(!yes)return;await dbOp('readwrite',s=>{for(const x of list)s.put({...x,id:crypto.randomUUID(),name:x.name.slice(0,100)+'（匯入）',deleted:false,imported:true})});await loadHistory();toast('已匯入獨立副本')}catch(e){toast('匯入失敗：'+e.message)}finally{e.target.value=''}};
function syncReviewButtons(){for(const b of $('historyList').querySelectorAll('[data-open]')){const open=b.dataset.open===openRecordId;b.textContent=open?'收回檢討':'檢討';b.setAttribute('aria-expanded',String(open))}}
function closeReview(){openRecordId=null;$('recordDetail').classList.add('hidden');syncReviewButtons()}
async function openRecord(id){if(openRecordId===id&&!$('recordDetail').classList.contains('hidden')){closeReview();return}openRecordId=id;syncReviewButtons();const x=allRecords.find(x=>x.id===id);$('recordDetail').classList.remove('hidden');$('recordDetail').innerHTML=`<div class="sectionhead"><h2>${esc(x.name)}</h2><button id="closeReview">收回檢討 ×</button></div><p>${esc(x.note)} ${x.imported?'（外部匯入紀錄）':''}</p>${statsHTML(x.stats)}<div class="equitywrap"><h3>含未實現損益的權益曲線</h3><canvas id="savedEquity"></canvas></div><h3>已平倉交易</h3>${tradeTable(x.trades)}<h3>事件紀錄（最近 200 筆）</h3>${table(['事件','時間','來源列序','委託'],x.events.slice(-200).reverse().map(e=>[esc(e.type),time(e.time),num(e.row),esc(e.order)]))}<p class="audit">來源檔案 SHA-256：${esc(x.sha256)}<br>參數快照：${esc(JSON.stringify(x.cfg))}</p>`;$('closeReview').onclick=closeReview;$('recordDetail').querySelectorAll('[data-trade]').forEach(b=>b.onclick=async()=>{try{const response=await fetch(`./data/${x.date}_${x.contract}.json`);if(!response.ok)throw Error('找不到原始行情');const d=await response.json();if(d.sha256!==x.sha256)throw Error('來源雜湊不符，無法回看');const state={data:d,orders:x.orders,bars:[]};inspectTrade(x.trades[Number(b.dataset.trade)],state)}catch(e){toast(e.message)}});requestAnimationFrame(()=>drawEquity($('savedEquity'),x.equity,x.cfg.capital));$('recordDetail').scrollIntoView({behavior:'smooth',block:'start'})}
$('guideBtn').onclick=()=>modal('<h2>曾阿牛的期貨島</h2><p>上方工具列開啟均線、下單手法、速度、日期及警示設定。日期預設隨機；開始回放，暫停停在目前位置，結束會結清持倉並清空本次紀錄與走勢圖；欲保留績效請先儲存。</p><p>四組均線預設5／10／15／30，可自行修改。走勢可放大、縮小、拖曳、回到最新或完整顯示；下方為對齊時間的成交量。</p><p>Z 開啟警示設定，預設全部關閉。各方向只通知首次觸發，新練習才重設。上午區間包含指定分鐘的完整行情，下一分鐘起判斷。缺少08:45開盤或前一交易日資料時，對應警示不推算。</p><p>本日進出紀錄可保存、檢討與匯出。歷史累積績效保存在目前瀏覽器；換電腦前請先匯出。A鍵開關小型閃電下單面板，可拖曳及切換現價、限價、停利停損、觸價。←／→只在現價面板開啟且未輸入時下單。限價採到價成交模型，買不高於、賣不低於委託價；現價與觸價採後續逐筆加滑價。停利停損空手可預掛，成交後綁定成本；先觸發一側即結束本組，僅平倉不反手。關閉面板保留已啟動委託。</p>',{ok:'關閉',cancel:false});
