window.addEventListener('beforeunload',e=>{if(hasWork()&&(r.i!==saveIndex||dirty)){e.preventDefault();e.returnValue=''}});
async function initialize({autoplay=false}={}){
 if(loading)return false;setBusy(true);feedback('正在載入行情清單…');
 try{
  manifest=await getJSON('./data/index.json');if(!Array.isArray(manifest)||!manifest.length)throw Error('行情清單沒有資料');
  alertReferences=await getJSON('./data/alert-reference.json');
  const dates=[...new Set(manifest.map(x=>x.date))].sort().reverse();$('dataCoverage').textContent=`資料期間：${dates.at(-1)}～${dates[0]}，${dates.length}個交易日。各契約分開回放，不自動拼接換月。`;$('date').innerHTML=dates.map(d=>`<option>${d}</option>`).join('');chooseRandomDate();setBusy(false);return await loadSession({force:true,autoplay});
 }catch(e){setBusy(false);$('status').textContent='行情載入失敗';$('emptyChart').textContent=e.message;feedback('行情載入失敗：'+e.message,true);$('load').textContent='重試載入';toast(e.message);return false}
}
function syncOrderWindow(){if(!orderUI)return;const p=r?.position,t=r?.tick;const summary=r?`TX ${r.data.contract} ｜ ${time(t[0])} ｜ 現價 ${num(t[1])} ｜ ${p?(p.side===1?'多單':'空單')+' '+p.qty+'口，浮動損益 TWD '+signed(r.unrealized):'空手'} ｜ ${playing?'回放中':'已暫停'}`:'正在載入行情';orderUI.sync({summary,title:p?(p.side===1?'多':'空')+p.qty+'口 '+signed(r.unrealized):'獨立下單',playLabel:$('play').textContent,disabled:loading||!r||r.finished})}
$('popoutOrders').onclick=()=>lightning.toggle(r?.tick?.[1]);
openDB().then(value=>{db=value}).catch(e=>{$('storageNotice').textContent='瀏覽器儲存暫時不可用：'+e.message+'。仍可回放與交易，請用 JSON 匯出保存。';$('storageNotice').hidden=false});
initialize();


function drawEquity(canvas,points,capital){if(!canvas||!points.length)return;const box=canvas.getBoundingClientRect(),w=box.width,h=box.height;if(!w||!h)return;const d=devicePixelRatio||1;canvas.width=w*d;canvas.height=h*d;const c=canvas.getContext('2d');c.scale(d,d);let lo=capital,hi=capital;for(const p of points){if(!Number.isFinite(p.value))return;lo=Math.min(lo,p.value);hi=Math.max(hi,p.value)}const pad=Math.max(100,(hi-lo)*.15);lo-=pad;hi+=pad;const y=v=>15+(hi-v)/(hi-lo)*(h-40);c.font='10px Arial';for(let i=0;i<4;i++){const v=lo+(hi-lo)*i/3;c.strokeStyle='#2a363e';c.beginPath();c.moveTo(0,y(v));c.lineTo(w-80,y(v));c.stroke();c.fillStyle='#8b9da8';c.fillText(num(v),w-72,y(v)+4)}c.strokeStyle='#d9bd79';c.beginPath();for(let i=0;i<points.length;i++){const xx=i/Math.max(1,points.length-1)*(w-84),yy=y(points[i].value);if(i===0)c.moveTo(xx,yy);else c.lineTo(xx,yy)}c.stroke();c.fillStyle='#8b9da8';c.fillText(time(points[0].time),0,h-4);c.fillText(time(points.at(-1).time),w-140,h-4)}

function setIslandLink(value){let url;try{url=new URL(value);if(!['https:','http:'].includes(url.protocol)||url.username||url.password)throw Error()}catch{throw Error('請輸入完整的 http 或 https 網址')}$('islandLink').href=url.href;$('islandLink').target='_blank';$('islandLink').rel='noopener noreferrer';$('islandURL').value=url.href;$('islandStatus').textContent='已設定：'+url.href;return url.href}
setIslandLink('https://cayman-ai.github.io/ice-fire-island/');
function fitField(field){if(field.closest('.lightningPanel')||!field.matches('input[type="number"],select'))return;const measuring=document.createElement('canvas').getContext('2d');const css=(field.ownerDocument.defaultView||window).getComputedStyle(field);measuring.font=css.fontSize+' '+css.fontFamily;const text=field.matches('select')?(field.selectedOptions[0]?.textContent??''):(field.value||field.placeholder||'0');const extra=(parseFloat(css.paddingLeft)||0)+(parseFloat(css.paddingRight)||0)+2+(field.matches('select')?30:30);const minimum=field.matches('select')?85:80;field.style.width=Math.max(minimum,Math.ceil(measuring.measureText(text).width+extra))+'px';field.style.maxWidth='100%'}
function fitFields(){document.querySelectorAll('input[type="number"],select').forEach(fitField);orderRoot.querySelectorAll('input[type="number"],select').forEach(fitField)}
document.addEventListener('input',e=>fitField(e.target));document.addEventListener('change',e=>fitField(e.target));fitFields();

function chooseRandomDate(){const dates=[...new Set(manifest.map(x=>x.date))];$('date').value=dates[Math.floor(Math.random()*dates.length)];contracts();const active=manifest.filter(x=>x.date===$('date').value).sort((a,b)=>b.count-a.count)[0];if(active)$('contract').value=active.contract;datePicker.sync()}
function alertConfig(){const points=id=>{const v=Number($(id).value);if(!Number.isInteger(v)||v<1)throw Error('警示點數請填入正整數');return v};const value=$('alertTime').value;if(!/^\d{2}:\d{2}$/.test(value))throw Error('請設定上午時間');const [h,m]=value.split(':').map(Number);const cutoff=h*3600+m*60+59;if(cutoff<31559||cutoff>=43200)throw Error('區間時間請設在08:45～11:59');return normalizeAlerts({amplitude:$('alertAmplitude').checked,amplitudePoints:points('alertAmplitudePoints'),openUp:$('alertOpenUp').checked,openDown:$('alertOpenDown').checked,upPoints:points('alertUpPoints'),downPoints:points('alertDownPoints'),rangeUp:$('alertRangeUp').checked,rangeDown:$('alertRangeDown').checked,cutoff,yesterdayUp:$('alertYesterdayUp').checked,yesterdayDown:$('alertYesterdayDown').checked})}
const alertTicker=new AlertTicker($('alertNotices')),alertStorageKey='futures-island-alerts-v1';
let activeAlertConfig=null;
function writeAlertFields(c){for(const [id,key] of Object.entries({alertOpenUp:'openUp',alertOpenDown:'openDown',alertRangeUp:'rangeUp',alertRangeDown:'rangeDown',alertYesterdayUp:'yesterdayUp',alertYesterdayDown:'yesterdayDown',alertAmplitude:'amplitude'}))$(id).checked=c[key];$('alertUpPoints').value=c.upPoints;$('alertDownPoints').value=c.downPoints;$('alertAmplitudePoints').value=c.amplitudePoints;$('alertTime').value=time(c.cutoff).slice(0,5);fitFields()}
try{const saved=localStorage.getItem(alertStorageKey);if(saved){activeAlertConfig=normalizeAlerts(JSON.parse(saved));writeAlertFields(activeAlertConfig);$('alertSaveState').textContent='已載入儲存的警示設定。儲存僅限目前瀏覽器；新練習重設通知次數。'}}catch{$('alertSaveState').textContent='無法讀取儲存設定，使用預設值。'}
function applyAlertSettings(c){activeAlertConfig=c;if(r){const fired=alertEngine?.fired??new Set();resetAlerts(false);alertEngine.fired=fired;processAlerts()}else $('alertState').textContent='已設定，開始練習後啟用';renderAlertStatus()}
$('saveAlerts').onclick=()=>{try{const c=alertConfig();localStorage.setItem(alertStorageKey,JSON.stringify(c));applyAlertSettings(c);$('alertSaveState').textContent='已儲存並套用，下次開啟沿用。本次已通知條件不重複通知。';toast('警示已儲存並套用')}catch(e){toast('未完成儲存：'+e.message)}};
$('resetAlertSettings').onclick=()=>{const c={...ALERT_DEFAULTS};writeAlertFields(c);applyAlertSettings(c);alertTicker.clear();try{localStorage.setItem(alertStorageKey,JSON.stringify(c));$('alertSaveState').textContent='已重設並儲存預設值，全部警示關閉。本次已通知條件保留至新練習。';toast('已重設警示，全部關閉')}catch(e){$('alertSaveState').textContent='本次已重設，但無法儲存至瀏覽器；重新開啟可能載入舊設定。';toast('本次已重設，儲存失敗：'+e.message)}};
function resetAlerts(clearLog=true){const extents=clearLog?{}:alertEngine?.extents??{};alertEngine=new Alerts(activeAlertConfig??alertConfig(),alertReferences[r.data.date+'_'+r.data.contract]);for(let i=0;i<=Math.max(0,r.i);i++)alertEngine.step(r.data.ticks[i],false);alertEngine.extents=extents;if(clearLog){$('alertLog').replaceChildren();alertTicker.clear();$('latestAlert').hidden=true}renderAlertStatus()}
function processAlerts(){if(!alertEngine||!r)return;for(const e of alertEngine.step(r.tick)){const line=document.createElement('div');line.textContent=time(e.time)+' ｜ '+e.message;line.className='alertLine';line.dataset.alertKey=e.key;$('alertLog').prepend(line);alertTicker.add(e.key,line.textContent);$('latestAlert').dataset.alertKey=e.key;$('latestAlert').textContent='● '+line.textContent;$('latestAlert').hidden=false}for(const e of alertEngine.updates){const text=time(e.time)+' ｜ '+e.message,line=$('alertLog').querySelector(`[data-alert-key="${e.key}"]`);if(line)line.textContent=text;alertTicker.update(e.key,text);if($('latestAlert').dataset.alertKey===e.key)$('latestAlert').textContent='● '+text}renderAlertStatus()}
function renderAlertStatus(){if(!alertEngine)return;const count=Object.values(alertEngine.config).filter(x=>x===true).length;$('alertState').textContent=count?`已啟用 ${count} 項；本次已通知 ${alertEngine.fired.size} 項`:'所有警示均關閉';$('yesterdayReference').textContent=alertEngine.previous?`前一交易日 ${alertEngine.previous.date}：高 ${num(alertEngine.previous.high)} ／ 低 ${num(alertEngine.previous.low)}`:'此契約缺少前一交易日資料，昨日高低點警示不可用。'}
$('applyAlerts').onclick=()=>{try{applyAlertSettings(alertConfig());toast('警示設定已套用；本次已通知條件不重設');$('alertMenu').close()}catch(e){toast(e.message)}};
