document.addEventListener('keydown',e=>{
 if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||e.isComposing)return;
 const key=e.key.toLowerCase(),editing=!!e.target.closest('textarea,[contenteditable="true"],input:not([type="number"]):not([type="checkbox"]):not([type="time"])');
 if(key==='z'&&$('alertMenu').open){e.preventDefault();$('alertMenu').close();return}
 if(editing||document.querySelector('dialog[open]'))return;
 if(key==='z'){e.preventDefault();$('alertMenu').showModal();return}
 if(key==='a'){e.preventDefault();$('popoutOrders').click();return}
 if(key==='d'){e.preventDefault();cancelAllOrders();return}
 if(key==='escape'&&lightning.visible){e.preventDefault();lightning.hide();return}
 if(!e.shiftKey&&['ArrowLeft','ArrowRight'].includes(e.key)&&lightning.visible&&lightning.tab==='market'&&!e.target.closest('input,textarea,select')&&!$('practice').classList.contains('hidden')){e.preventDefault();lightning.submit(e.key==='ArrowLeft'?'marketBuy':'marketSell')}
});
function requireTrading(manual=false){if(!r||loading||r.finished)throw Error('請先開始未結束的練習');if($('practice').classList.contains('hidden'))throw Error('請返回走勢圖後下單');if(manual&&r.cfg.auto)throw Error('請改用手動練習後下單')}
function sendLightning(input){requireTrading(true);const o=r.submit({...input,flatOnly:false,tp:0,sl:0});dirty=true;render();toast(`委託 #${o.id} 已送出，${input.kind==='limit'?'等待限價到價':(input.condition||input.touch)?'等待觸價':'等待下一筆成交'}`)}
function renderLightning(){if(!r||!lightning)return;const p=r.position;$('stripSide').textContent=p?`${p.side===1?'多單':'空單'} ${p.qty}口`:'空手 0口';$('stripCost').textContent=p?'成本均價 '+num(p.price,2):'成本均價 —';$('stripPNL').textContent='即時損益 TWD '+signed(r.unrealized);$('stripPNL').className=tone(r.unrealized);$('stripClose').disabled=!p||r.finished||loading;lightning.update({quote:`TX ${r.data.contract} ｜ ${time(r.tick[0])} ｜ 現價 ${num(r.tick[1])}`,session:r,orders:r.orders,plan:r.protection,disabled:loading||r.finished,auto:r.cfg.auto})}
function cancelAllOrders(){if(!r||loading)return;const result=r.cancelAll();dirty=true;render();toast(`已刪除 ${result.orders} 筆未成交委託${result.protection?'，並停用停利停損':''}；現有持倉保留${r.cfg.auto?'。自動策略仍啟用':''}`)}
lightning=new LightningPanel({onProtectionSide:(key,input)=>{requireTrading();r.setProtectionSide(key,input);dirty=true;render();toast((key==='tp'?'停利':'停損')+(input.enabled?'已開啟':'已關閉'))},onCancelAll:cancelAllOrders,onOrder:sendLightning,onProtection:input=>{requireTrading();const plan=r.setProtection(input);dirty=true;render();toast(plan.status==='active'?`停利停損已啟動，基準成本 ${num(plan.anchor,2)}`:'停利停損已啟動，等待下一次持倉成交')},onCancel:id=>{if(!r)return;r.cancel(id);dirty=true;render();toast('已取消委託 #'+id)},onCancelProtection:()=>{if(!r)return;r.cancelProtection();dirty=true;render();toast('已取消本組停利停損')},onMessage:toast});
$('stripClose').onclick=()=>{try{requireTrading();if(!r.position)throw Error('目前沒有持倉');const o=r.submit({close:true,qty:r.position.qty,reason:'持倉列平倉'});dirty=true;render();toast(`平倉委託 #${o.id} 已送出，等待下一筆成交`)}catch(e){toast(e.message)}};

let statisticsData=null;
function renderStatistics(scope='recent',preserve=false){const root=$('statisticsContent'),chartOpen=preserve&&Boolean(root.querySelector('.extremesPanel .chartDisclosure')?.open),rangeOpen=preserve&&Boolean(root.querySelector('.previousRangePanel details')?.open);root.innerHTML=statisticsHTML(statisticsData,scope);const chart=root.querySelector('.extremesPanel .chartDisclosure');if(chart)chart.open=chartOpen;root.querySelector('.distributionToggle')?.setAttribute('aria-expanded',String(chartOpen));const range=root.querySelector('.previousRangePanel details');if(range)range.open=rangeOpen;const select=$('extremesScope');if(select)select.onchange=()=>renderStatistics(select.value,true)}
async function loadStatistics(){try{statisticsData=await getJSON('./data/statistics.json');renderStatistics()}catch(e){$('statisticsContent').textContent='統計資料讀取失敗：'+e.message}}

function renderEntryTimeAnalysis(){const target=$('entryTimeAnalysis'),wasOpen=target.querySelector('details.statDisclosure')?.open??false;target.innerHTML=entryTimeHTML(entryTimeAnalysis(allRecords,{scope:entryTimeScope,mode:entryTimeMode}));target.querySelector('details.statDisclosure').open=wasOpen;$('entryTimeScope').onchange=()=>{entryTimeScope=$('entryTimeScope').value;renderEntryTimeAnalysis()};$('entryTimeMode').onchange=()=>{entryTimeMode=$('entryTimeMode').value;renderEntryTimeAnalysis()}}
